      </p>
      <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
        {SEED.map((item, i) => (
          <motion.button
            key={item.id}
            onClick={() => setActive(i)}
            animate={{ scale: active === i ? 1.08 : 1, backgroundColor: active === i ? '#B8B800' : '#FFFFFF' }}
            transition={{ type: 'spring', stiffness: 300 }}
            style={{
              padding: '12px 20px',
              border: '1px solid #0D0D0D',
